 12 │ /**
 13 │  * {@link IdempotentExecution} over the claim mechanics of {@link IdempotencyClaims}: the
 14 │  * three phases of design decision 4, with design decision 5's four answers decided between
 15 │  * the first and the last.
 16 │  *
 17 │  * <p>The order below is the whole of the guarantee, and no two steps are interchangeable:
 18 │  *
 19 │  * <ol>
 20 │  * <li>claim the key, where the unique constraint — not a preceding read — is what
 21 │  * discovers a duplicate;
 22 │  * <li>if it was refused, read the claim that beat this one and answer from it, without
 23 │  * ever reaching the operation;
 24 │  * <li>otherwise run the operation and close the claim, in one transaction that commits
 25 │  * both or neither.
 26 │  * </ol>
 27 │  *
 28 │  * <p>Phase two of design decision 4 — resolving anything slow with no locks held — has no
 29 │  * slot here, because there is nothing to resolve until ticket 26 fetches an Exchange Rate.
 30 │  * It is not a hole in the ordering: duplicate resolution already happens above everything,
 31 │  * so a duplicate never reaches whatever ends up between the claim and the transaction.
 32 │  *
 33 │  * <p>Package-private, like everything else in this slice. What another slice may hold is
 34 │  * the port.
 35 │  */
 36 │ @Service
 37 │ class ClaimedExecution implements IdempotentExecution {
 38 │ 
 39 │ 	private final IdempotencyClaims claims;
 40 │ 
 41 │ 	private final IdempotencyRecordRepository records;
 42 │ 
 43 │ 	private final ObjectMapper json;
 44 │ 
 45 │ 	/**
 46 │ 	 * The phase-three transaction, opened by hand rather than declared with
 47 │ 	 * {@code @Transactional}, for two reasons that both come from ticket 16.
 48 │ 	 *
 49 │ 	 * <p>An annotation on a method of this class called from another method of this class
 50 │ 	 * is not proxied at all, so the transaction would silently not exist and
 51 │ 	 * {@link IdempotencyClaims#markSucceeded}'s {@code MANDATORY} propagation would be the
 52 │ 	 * only thing to say so. And the release of a failed claim has to happen <em>after</em>
 53 │ 	 * this transaction has ended rather than inside it, which is a line of code with a
 54 │ 	 * template and an invisible property of the method boundary with an annotation.
 55 │ 	 */
 56 │ 	private final TransactionTemplate transaction;
 57 │ 
 58 │ 	ClaimedExecution(IdempotencyClaims claims, IdempotencyRecordRepository records, ObjectMapper json,
 59 │ 			PlatformTransactionManager transactionManager) {
 60 │ 		this.claims = claims;
 61 │ 		this.records = records;
 62 │ 		this.json = json;
 63 │ 		this.transaction = new TransactionTemplate(transactionManager);
 64 │ 	}
 65 │ 
 66 │ 	@Override
 67 │ 	public <T> T executeOnce(String idempotencyKey, String payloadHash, Class<T> responseType,
 68 │ 			Supplier<T> operation) {
 69 │ 		try {
 70 │ 			claims.claim(idempotencyKey, payloadHash);
 71 │ 		}
 72 │ 		catch (DataIntegrityViolationException duplicate) {
 73 │ 			Optional<T> alreadyAnswered =
 74 │ 					replayOrReclaim(idempotencyKey, payloadHash, responseType, duplicate);
 75 │ 			if (alreadyAnswered.isPresent()) {
 76 │ 				return alreadyAnswered.get();
 77 │ 			}
 78 │ 		}
 79 │ 		return runUnderTheClaim(idempotencyKey, operation);
 80 │ 	}
 81 │ 
 82 │ 	/**
 83 │ 	 * Design decision 5's table, read off the claim that already holds the key.
 84 │ 	 *
 85 │ 	 * <p>An empty result means this caller now holds the key and should go on to execute,
 86 │ 	 * which is the {@code FAILED} row and the only one that is neither an answer nor a
 87 │ 	 * refusal. Every other row either returns the first request's response or throws.
 88 │ 	 *
 89 │ 	 * <p><b>An absent row rethrows the violation rather than assuming this was the key's.</b>
 90 │ 	 * It is the guard that keeps the duplicate path from swallowing an insert some other
 91 │ 	 * constraint refused — a payload hash of the wrong length, say — which would otherwise
 92 │ 	 * surface as a {@code 409} naming a claim that does not exist. Matching on the
 93 │ 	 * constraint's name would answer the same question and would tie this class to a string
 94 │ 	 * H2 and PostgreSQL format differently.
 95 │ 	 *
 96 │ 	 * <p>The payload is compared before the status is looked at, which is what makes the
 97 │ 	 * mismatch one row of that table rather than three. A repeat carrying a different
 98 │ 	 * payload is a client mistake whatever the first request got to — and answering it from
 99 │ 	 * a {@code SUCCEEDED} claim would hand a client the response to a request it never made.
100 │ 	 */
101 │ 	private <T> Optional<T> replayOrReclaim(String idempotencyKey, String payloadHash,
102 │ 			Class<T> responseType, DataIntegrityViolationException violation) {
103 │ 		IdempotencyRecord claimed = records.findByIdempotencyKey(idempotencyKey)
104 │ 				.orElseThrow(() -> violation);
105 │ 
106 │ 		if (!claimed.getPayloadHash().equals(payloadHash)) {
107 │ 			throw new IdempotencyKeyReusedException(idempotencyKey);
108 │ 		}
109 │ 
110 │ 		return switch (claimed.getStatus()) {
111 │ 			case IN_PROGRESS -> throw new RequestInProgressException(idempotencyKey);
112 │ 			case SUCCEEDED -> Optional.of(json.readValue(claimed.getResponseBody(), responseType));
113 │ 			case FAILED -> reclaimed(idempotencyKey);
114 │ 		};
115 │ 	}
116 │ 
117 │ 	/**
118 │ 	 * The loser of a race for a failed key is told the request is in progress, and by then it
119 │ 	 * is: the winner is holding the claim it just took. Ticket 18 provokes this branch, which
120 │ 	 * no single-threaded test can reach.
121 │ 	 */
122 │ 	private <T> Optional<T> reclaimed(String idempotencyKey) {
123 │ 		if (!claims.reclaimFailed(idempotencyKey)) {
124 │ 			throw new RequestInProgressException(idempotencyKey);
125 │ 		}
126 │ 		return Optional.empty();
127 │ 	}
128 │ 
129 │ 	/**
130 │ 	 * Phase three: the operation and the flip to {@code SUCCEEDED} in one transaction, and
131 │ 	 * the release of the claim strictly outside it.
132 │ 	 *
133 │ 	 * <p>The {@code catch} sits outside the template deliberately. Releasing a claim commits
134 │ 	 * on its own so that it survives the rollback it reports, and a new transaction cannot
135 │ 	 * see the locks the failing one is still holding — so releasing from inside would wait on
136 │ 	 * a row lock only the transaction it is running within can release. Ticket 16 measured it
137 │ 	 * at a two-second timeout ending with the row stranded at {@code IN_PROGRESS}, which is
138 │ 	 * the one state this whole path exists to prevent.
139 │ 	 */
140 │ 	private <T> T runUnderTheClaim(String idempotencyKey, Supplier<T> operation) {
141 │ 		try {
142 │ 			return transaction.execute(status -> {
143 │ 				T answer = operation.get();
144 │ 				claims.markSucceeded(idempotencyKey, json.writeValueAsString(answer));
145 │ 				return answer;
146 │ 			});
147 │ 		}
148 │ 		catch (RuntimeException failure) {
149 │ 			release(idempotencyKey, failure);
150 │ 			throw failure;
151 │ 		}
152 │ 	}
153 │ 
154 │ 	/**
155 │ 	 * A claim that cannot be released is reported attached to the failure that was being
156 │ 	 * released for, never instead of it: the caller asked about the operation, and a key
157 │ 	 * stranded by bookkeeping is a second fact rather than a replacement for the first.
158 │ 	 */
159 │ 	private void release(String idempotencyKey, RuntimeException failure) {
160 │ 		try {
161 │ 			claims.markFailed(idempotencyKey);
162 │ 		}
163 │ 		catch (RuntimeException unrecorded) {
164 │ 			failure.addSuppressed(unrecorded);
165 │ 		}
166 │ 	}
